CREATE DEFINER=`root`@`localhost` PROCEDURE `CheckInstructorPC`(
	IN in_ip VARCHAR(255),
    Out return_count BOOL,
    Out return_state INT
)
BEGIN
    DECLARE cnt INT DEFAULT 0;
    
	DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    BEGIN
        SET return_state = 0;
    END;
    
-- 사용자의 정보를 입력 한다.
	Select COUNT(*) into cnt 
    from `lllegaldrone`.`instructordb` 
    where ip = in_ip;    
    
	IF cnt > 0 THEN
        SET return_count = TRUE;  -- true로 설정
    ELSE
        SET return_count = FALSE;  -- false로 설정
    END IF;
    
    SET return_state = 1;
END ;;
