CREATE DEFINER=`root`@`localhost` PROCEDURE `GetTraineeInfos`(
    IN in_offset INT,
    IN in_maxCnt INT,
    IN in_asc BOOL,
    IN in_name VARCHAR(255),
    IN in_issearch BOOL,
    IN in_userGroup INT,
    OUT return_state INT
)
BEGIN    
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    BEGIN
        SET return_state = 0;
    END;

    IF in_asc THEN
		WITH LatestPlay AS (
			SELECT 
				p.UserID, 
				MAX(p.PlayScenarioDateTime) AS LatestPlayDate
			FROM 
				lllegaldrone.playdb p
			GROUP BY 
				p.UserID
		),
		LatestPlayDetails AS (
			SELECT 
				p.UserID,
				p.PlayScenarioDateTime,
				p.ScenarioID,
				p.Missionresult,
				ROW_NUMBER() OVER (PARTITION BY p.UserID ORDER BY p.PlayScenarioDateTime DESC) AS rn
			FROM 
				lllegaldrone.playdb p
		)

		SELECT 
			ROW_NUMBER() OVER (ORDER BY u.CreateIDDate) AS idx,
			u.CreateIDDate, 
			u.ID, 
			u.UserName, 
			COALESCE(playCount.Count, 0) AS Scenariocount,
			lp.LatestPlayDate,
			s.PlayMode,
			lpd.Missionresult,
			CASE 
				WHEN lpd.PlayScenarioDateTime IS NULL THEN 'false'
				WHEN DATEDIFF(CURRENT_DATE, lpd.PlayScenarioDateTime) > 90 THEN 'false' 
				ELSE 'true' 
			END AS btnActive,
			u.CreateAdminName
		FROM 
			lllegaldrone.userdb u
		LEFT JOIN 
			LatestPlay lp ON lp.UserID = u.ID
		LEFT JOIN 
			LatestPlayDetails lpd ON lpd.UserID = u.ID AND lpd.rn = 1  -- 최신 데이터만 선택
		LEFT JOIN 
			lllegaldrone.scenariodb s ON s.ScenarioID = lpd.ScenarioID
		LEFT JOIN (
			SELECT 
				UserID, 
				COUNT(*) AS Count 
			FROM 
				lllegaldrone.playdb 
			GROUP BY 
				UserID
		) AS playCount ON playCount.UserID = u.ID
		WHERE 
			u.Usergroup = 2
			AND (u.UserName LIKE CONCAT('%', in_name, '%'))
		ORDER BY 
			idx asc  -- 올바른 정렬
		LIMIT in_maxCnt OFFSET in_offset;

    ELSE
				WITH LatestPlay AS (
			SELECT 
				p.UserID, 
				MAX(p.PlayScenarioDateTime) AS LatestPlayDate
			FROM 
				lllegaldrone.playdb p
			GROUP BY 
				p.UserID
		),
		LatestPlayDetails AS (
			SELECT 
				p.UserID,
				p.PlayScenarioDateTime,
				p.ScenarioID,
				p.Missionresult,
				ROW_NUMBER() OVER (PARTITION BY p.UserID ORDER BY p.PlayScenarioDateTime DESC) AS rn
			FROM 
				lllegaldrone.playdb p
		)

		SELECT 
			ROW_NUMBER() OVER (ORDER BY u.CreateIDDate) AS idx,
			u.CreateIDDate, 
			u.ID, 
			u.UserName, 
			COALESCE(playCount.Count, 0) AS Scenariocount,
			lp.LatestPlayDate,
			s.PlayMode,
			lpd.Missionresult,
			CASE 
				WHEN lpd.PlayScenarioDateTime IS NULL THEN 'false'
				WHEN DATEDIFF(CURRENT_DATE, lpd.PlayScenarioDateTime) > 90 THEN 'false' 
				ELSE 'true' 
			END AS btnActive,
			u.CreateAdminName
		FROM 
			lllegaldrone.userdb u
		LEFT JOIN 
			LatestPlay lp ON lp.UserID = u.ID
		LEFT JOIN 
			LatestPlayDetails lpd ON lpd.UserID = u.ID AND lpd.rn = 1  -- 최신 데이터만 선택
		LEFT JOIN 
			lllegaldrone.scenariodb s ON s.ScenarioID = lpd.ScenarioID
		LEFT JOIN (
			SELECT 
				UserID, 
				COUNT(*) AS Count 
			FROM 
				lllegaldrone.playdb 
			GROUP BY 
				UserID
		) AS playCount ON playCount.UserID = u.ID
		WHERE 
			u.Usergroup = 2
			AND (u.UserName LIKE CONCAT('%', in_name, '%'))
		ORDER BY 
			idx desc  -- 올바른 정렬
		LIMIT in_maxCnt OFFSET in_offset;
    END IF;

    SET return_state = 1;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `GetTraineeTraingParcent` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `GetTraineeTraingParcent`(
    IN in_id VARCHAR(255),
    OUT return_percent DOUBLE,
    OUT return_state INT
)
BEGIN
    -- 변수 선언
    DECLARE total_count INT;
    DECLARE success_count INT;

    -- 예외 발생 시 처리
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    BEGIN
        SET return_state = 0;  -- 실패 상태
        SET return_percent = -1;  -- 실패 시 비율
    END;

    -- 전체 미션 수 계산
    SELECT COUNT(*) INTO total_count
    FROM lllegaldrone.playdb
    WHERE UserID = in_id;

    -- 성공한 미션 수 계산
    SELECT SUM(CASE WHEN TeamMissionresult = 1 THEN 1 ELSE 0 END) INTO success_count
    FROM lllegaldrone.playdb
    WHERE UserID = in_id;

    -- 비율 계산 및 소수점 2자리로 반올림
    IF total_count > 0 THEN
        SET return_percent = ROUND((success_count * 100.0 / total_count), 2);
    ELSE
        SET return_percent = 0;  -- 미션이 없을 경우 비율 0
    END IF;


    SET return_state = 1;  -- 성공 상태
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `GetTraineeTrainInfos` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `GetTraineeTrainInfos`(
    IN in_offset INT,
    IN in_maxCnt INT,
    IN in_asc BOOL,
    IN in_userid VARCHAR(255),
    OUT return_state INT
)
BEGIN
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    BEGIN
        SET return_state = 0;
    END;

    -- 기본 쿼리
    SET @order := CASE WHEN in_asc THEN 'ASC' ELSE 'DESC' END;
                                                
	SET @sql := CONCAT('SELECT 
						rankedPlayers.idx, 
						rankedPlayers.PlayScenarioDateTime, 
						s.MissionMap, 
						s.Weather, 
						s.TimeZone, 
						s.PlayMode, 
						rankedPlayers.PlayScenarioTime, 
						s.limitPlaytime, 
						rankedPlayers.Missionresult, 
						CASE 
							WHEN u.Usergroup = 1 THEN -1 
							ELSE rankedPlayers.ranks 
						END AS ranks,
						CASE 
							WHEN rankedPlayers.PlayScenarioDateTime IS NULL THEN "false"
							WHEN DATEDIFF(CURRENT_DATE, rankedPlayers.PlayScenarioDateTime) > 90 THEN "false"
							ELSE "true"
						END AS btnActive,
                        s.CreateUser as Admin
					FROM (
						SELECT 
							p.idx, 
							p.PlayScenarioDateTime, 
							p.UserID, 
							p.KillCount, 
							p.ScenarioID, 
							p.TeamMissionresult as Missionresult,
							p.PlayScenarioTime,
							RANK() OVER (PARTITION BY p.ScenarioID ORDER BY p.KillCount DESC) AS ranks
						FROM lllegaldrone.playdb p    
					) AS rankedPlayers
					INNER JOIN lllegaldrone.scenariodb s ON rankedPlayers.ScenarioID = s.ScenarioID
					INNER JOIN lllegaldrone.userdb u ON rankedPlayers.UserID = u.ID
					WHERE rankedPlayers.UserID = ?
					ORDER BY rankedPlayers.PlayScenarioDateTime ', @order, ', rankedPlayers.ScenarioID, ranks
                    LIMIT ? OFFSET ?;');
                        
    -- Prepare statement
    PREPARE stmt FROM @sql;

    SET @UserID = in_userid;
    SET @maxCnt = in_maxCnt;
    SET @offset = in_offset;

    -- Execute statement
    EXECUTE stmt USING @UserID, @maxCnt, @offset;
    
    -- Cleanup
    DEALLOCATE PREPARE stmt;
    
    SET return_state = 1;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `GetTrainingCumulativeCount` */;
